<script setup lang="ts">
import BusinessStatus from '../components/BusinessStatus.vue';
import {businessTone} from '../business-status';
import {computed,onMounted,reactive,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {ElMessage,ElMessageBox} from 'element-plus';
import {api,get,message} from '../api';
import {useAuth} from '../stores/auth';
import Icon from '../components/Icon.vue';
import GrainImage from '../components/GrainImage.vue';
import { supplyRange,supplyLoading,supplyQuotes } from '../supply-format';
import {ton} from '../fulfillment';
const tonnes=(value:number)=>Number(value||0).toFixed(1);
const auth=useAuth(),route=useRoute(),router=useRouter();
const trader=computed(()=>auth.user?.businessEntity.type==='TRADER'),carrier=computed(()=>auth.user?.businessEntity.type==='CARRIER'),platform=computed(()=>auth.user?.businessEntity.type==='PLATFORM');
const view=ref(route.query.view==='list'?'list':'cards');
const tab=ref(['mine','supply'].includes(String(route.query.tab))?String(route.query.tab):'demand'),rows=ref<any[]>([]),selected=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),options=ref<any>({demands:[],carriers:[],grains:[],modes:[]});
const query=reactive({minQuantity:route.query.minQuantity?Number(route.query.minQuantity):undefined,maxQuantity:route.query.maxQuantity?Number(route.query.maxQuantity):undefined,departureFrom:String(route.query.departureFrom||''),departureTo:String(route.query.departureTo||''),carrierId:String(route.query.carrierId||''),q:String(route.query.q||''),publicationMode:String(route.query.publicationMode||''),order:String(route.query.order||'desc'),scope:String(route.query.scope||'all'),status:String(route.query.status||''),type:String(route.query.type||''),grainId:String(route.query.grainId||''),modeId:String(route.query.modeId||''),origin:String(route.query.origin||''),destination:String(route.query.destination||''),page:Math.max(1,Number(route.query.page)||1),pageSize:10});
const mine=computed(()=>tab.value==='mine'),demandView=computed(()=>mine.value?trader.value:tab.value==='demand');
function emptyRecommendation(row:any){if(demandView.value){if(row.remainingKg<=0)return '本次运输数量已全部落实，保留发布和报价记录。';if(row.status!=='ACTIVE'||new Date(row.deadline)<=new Date())return '本次发布已结束，保留历史记录。';return '暂无适配的已发布运力，可调整条件或稍后刷新。';}if(row.status!=='PUBLISHED')return '供给暂停或已失效，恢复发布后继续匹配。';return '暂无适配的有效需求，可调整条件或稍后刷新。';}
const names:Record<string,string>={INITIALIZATION:'待核对',PUBLISHED:'已发布',PAUSED:'已暂停',ACTIVE:'响应中',CLOSED:'已关闭',EXPIRED:'已截止',MATCHED:'已匹配',WAITING:'待报价',BIDDING:'报价中',NEGOTIATING:'议价中',PENDING_CONFIRM:'待确认承运',PARTIAL:'部分匹配',REMATCH:'待重新匹配',OPEN:'待回应',ACCEPTED:'双方已接受',REJECTED:'已拒绝',WITHDRAWN:'已撤回',CONFIRMED:'已确认承运',CANCELLED:'已取消',OFFER:'提交报价',COUNTER:'提出新条款',ACCEPT:'接受条款',REJECT:'拒绝条款',WITHDRAW:'撤回条款',TOTAL:'元/单',PER_TON:'元/吨',ROAD:'公路',RAIL:'铁路',WATER:'水运'};
const label=(s:string)=>names[s]||s,date=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'—',money=(v:number)=>'¥ '+(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
let request=0;
watch(tab,()=>{request++;rows.value=[];selected.value=[];total.value=0;},{flush:'sync'});
async function load(){const token=++request;loading.value=true;error.value='';selected.value=[];try{const data=await get('/matches/'+(mine.value?'mine':demandView.value?'publications':'supplies'),{...Object.fromEntries(Object.entries(query).filter(([,v])=>v!==''&&v!=null)),scope:mine.value?'owned':'all'});if(token===request){rows.value=data.items;total.value=data.total;}}catch(e){if(token===request)error.value=message(e);}finally{if(token===request)loading.value=false;}}
async function search(){query.page=1;await syncUrl();await load();}
async function syncUrl(){await router.replace({query:{...query,tab:tab.value,view:view.value,...(detailOpen.value&&detail.value?{id:detail.value.id}:{})}});}
function reset(){Object.assign(query,{minQuantity:undefined,maxQuantity:undefined,departureFrom:'',departureTo:'',carrierId:'',q:'',publicationMode:'',order:'desc',scope:'all',status:'',type:'',grainId:'',modeId:'',origin:'',destination:'',page:1});search();}
function switchTab(){recommendationOpen.value=false;query.publicationMode='';query.status='';query.type='';search();}
const detail=ref<any>(null),detailOpen=ref(false),detailLoading=ref(false),detailError=ref(''),saving=ref(false);
async function openDetail(id:string){detailOpen.value=true;detailLoading.value=true;detailError.value='';try{detail.value=await get('/matches/publications/'+id);await syncUrl();}catch(e){detail.value=null;detailError.value=message(e);}finally{detailLoading.value=false;}}
function closed(){const q={...route.query};delete q.id;router.replace({query:q});}
const active=computed(()=>detail.value?.status==='ACTIVE'&&new Date(detail.value.deadline)>new Date());
const myResponse=computed(()=>detail.value?.responses.find((r:any)=>r.carrierId===auth.user?.businessEntityId));
const recommendationOpen=ref(false),recommendationRow=ref<any>(null),recommendationLoading=ref(false),recommendationError=ref('');
async function openRecommendations(row:any){recommendationRow.value=row;recommendationOpen.value=true;recommendationLoading.value=true;recommendationError.value='';try{const data=await get('/matches/recommendations/'+(demandView.value?'demand':'supply')+'/'+row.id);recommendationRow.value={...row,recommendations:data.items,recommendationCount:data.total};}catch(e){recommendationError.value=message(e);}finally{recommendationLoading.value=false;}}
async function inviteRecommended(r:any){saving.value=true;recommendationError.value='';try{await api.post('/matches/publications/'+recommendationRow.value.id+'/invitations',{version:recommendationRow.value.version,carrierIds:[r.carrierId],supplyId:r.supplyId});const id=recommendationRow.value.id;await load();const updated=rows.value.find(row=>row.id===id);if(updated)await openRecommendations(updated);ElMessage.success('已邀请该物流运营商报价');}catch(e){recommendationError.value=message(e);}finally{saving.value=false;}}
async function quoteRecommended(r:any){const source=recommendationRow.value;recommendationOpen.value=false;await openDetail(r.publicationId);if(!detail.value||detailError.value||!active.value||myResponse.value)return;editQuote();if(!myResponse.value){const cents=detail.value.quoteType==='TOTAL'?r.totalCents:r.unitPriceCents;terms.price=cents==null?null:cents/100;terms.capability=source.resourceDescription||source.capabilities||'可提供适配本需求的运输资源';}}
const inviteOpen=ref(false),inviteError=ref(''),inviteLoading=ref(false),inviteSupplyRow=ref<any>(null),invitePublications=ref<any[]>([]),invitePublicationId=ref('');
async function inviteSupply(row:any){inviteSupplyRow.value=row;inviteOpen.value=true;inviteError.value='';invitePublicationId.value='';invitePublications.value=[];inviteLoading.value=true;try{invitePublications.value=(await get('/matches/my-publications')).items;}catch(e){inviteError.value=message(e);}finally{inviteLoading.value=false;}}
async function sendSupplyInvitation(){const p=invitePublications.value.find(p=>p.id===invitePublicationId.value);if(!p){inviteError.value='请选择本人已发布的运输需求或方案';return;}saving.value=true;inviteError.value='';try{await api.post('/matches/publications/'+p.id+'/invitations',{version:p.version,carrierIds:[inviteSupplyRow.value.carrier.id],supplyId:inviteSupplyRow.value.id});inviteOpen.value=false;ElMessage.success('邀请已保存，可在“我的”查看报价进度');}catch(e){inviteError.value=message(e);}finally{saving.value=false;}}
const publishOpen=ref(false),publishError=ref(''),supply=ref<any>(null);
const publication=reactive<any>({demandId:'',planRunId:'',mode:'PUBLIC',targetCarrierIds:[],deadline:'',quoteType:'TOTAL',allowPartial:false,budgetPublic:false,contactPublic:false,riskAcknowledged:false,notes:''});
const demand=computed(()=>options.value.demands.find((d:any)=>d.id===publication.demandId));
async function publish(s?:any,planId?:string,demandId?:string){publishError.value='';try{if(!mine.value){tab.value='mine';query.page=1;await syncUrl();await load();}options.value=await get('/matches/options');supply.value=s||null;const d=planId?options.value.demands.find((d:any)=>d.plans.some((p:any)=>p.id===planId)):options.value.demands.find((d:any)=>d.id===demandId);Object.assign(publication,{demandId:d?.id||'',planRunId:planId||'',mode:s?'DIRECTED':'PUBLIC',targetCarrierIds:s?[s.carrier.id]:[],deadline:'',quoteType:'TOTAL',allowPartial:false,budgetPublic:false,contactPublic:false,riskAcknowledged:false,notes:''});publishOpen.value=true;if((planId||demandId)&&!d)publishError.value='该需求已有有效发布或不再可发布，请在需求大厅查看发布记录。';}catch(e){ElMessage.error(message(e));}}
async function savePublish(){if(!demand.value||!publication.deadline||publication.mode==='DIRECTED'&&!publication.targetCarrierIds.length){publishError.value='请选择需求、响应截止时间和邀约议价企业';return;}saving.value=true;publishError.value='';try{const payload={...publication,version:demand.value.version};if(!payload.planRunId)delete payload.planRunId;if(payload.mode==='PUBLIC')delete payload.targetCarrierIds;if(supply.value&&payload.targetCarrierIds?.length===1)payload.supplyId=supply.value.id;const result=(await api.post('/matches/publications',payload)).data.data;publishOpen.value=false;tab.value='mine';await load();await openDetail(result.id);ElMessage.success('已发布，等待承运商报价');}catch(e){publishError.value=message(e);}finally{saving.value=false;}}
const quoteOpen=ref(false),quoteError=ref(''),response=ref<any>(null),terms=reactive<any>({}),quoteRef=ref<any>();
function editQuote(r?:any){response.value=r||null;quoteError.value='';const p=detail.value,s=p.snapshot;Object.assign(terms,{quantity:p.remainingKg/1000,price:null,unit:p.quoteType,taxIncluded:true,departureAt:s.departureAt,arrivalAt:s.arrivalAt||'',validUntil:p.deadline,capability:'',followOriginalPlan:true,note:''});if(r){for(const k of Object.keys(terms))terms[k]=r.terms[k];}quoteOpen.value=true;}
async function refreshQuoteContext(){try{const current=await get('/matches/publications/'+detail.value.id);detail.value=current;if(response.value)response.value=current.responses.find((r:any)=>r.id===response.value.id);quoteError.value='已刷新当前状态，草稿内容保留。请核对条款后提交。';}catch(e){quoteError.value=message(e);}}
async function saveQuote(){if(!terms.quantity||!terms.price||!terms.departureAt||!terms.arrivalAt||!terms.validUntil||!terms.capability?.trim()){quoteError.value='请填写数量、价格、服务时间、报价有效期和承运能力说明';return;}saving.value=true;quoteError.value='';try{const p=detail.value;await api.post(response.value?`/matches/responses/${response.value.id}/negotiate`:`/matches/publications/${p.id}/quote`,response.value?{version:response.value.version,publicationVersion:p.version,action:'COUNTER',terms:{...terms},note:terms.note}:{publicationVersion:p.version,terms:{...terms}});quoteOpen.value=false;await openDetail(p.id);await load();ElMessage.success('报价条款已保存');}catch(e){quoteError.value=message(e);}finally{saving.value=false;}}
async function act(r:any,action:string){try{await ElMessageBox.confirm(action==='CONFIRM'?`确认由 ${r.carrier.name} 承运 ${tonnes(r.terms.quantity)} 吨，成交总价 ${money(r.terms.totalCents)}？确认结果将作为后续合同依据。`:`${label(action)}当前报价：${tonnes(r.terms.quantity)} 吨，${money(r.terms.totalCents)}。`,action==='CONFIRM'?'确认承运':label(action),{confirmButtonText:'确认',cancelButtonText:'返回',type:'warning'});saving.value=true;detailError.value='';await api.post(`/matches/responses/${r.id}/${action==='CONFIRM'?'confirm':'negotiate'}`,{version:r.version,publicationVersion:detail.value.version,...(action==='CONFIRM'?{}:{action,note:''})});await openDetail(detail.value.id);await load();ElMessage.success('操作成功');}catch(e){if(e!=='cancel'&&e!=='close')detailError.value=message(e);}finally{saving.value=false;}}
async function closePublication(){try{const result=await ElMessageBox.prompt('关闭后停止报价，已确认的承运数量仍保留。请填写原因。','关闭发布',{inputValidator:(v:string)=>v?.trim().length>=2||'请填写至少两个字',confirmButtonText:'关闭发布',cancelButtonText:'返回'});saving.value=true;await api.post(`/matches/publications/${detail.value.id}/close`,{version:detail.value.version,reason:result.value});await openDetail(detail.value.id);await load();}catch(e){if(e!=='cancel'&&e!=='close')detailError.value=message(e);}finally{saving.value=false;}}
async function cancelConfirmation(c:any){try{const result=await ElMessageBox.prompt(`取消后释放 ${ton(c.quantityKg)}承运数量，保留历史记录。请填写原因。`,'取消承运确认',{inputValidator:(v:string)=>v?.trim().length>=2||'请填写至少两个字',confirmButtonText:'确认取消',cancelButtonText:'返回'});saving.value=true;await api.post(`/matches/confirmations/${c.id}/cancel`,{version:c.version,reason:result.value});await openDetail(detail.value.id);await load();}catch(e){if(e!=='cancel'&&e!=='close')detailError.value=message(e);}finally{saving.value=false;}}
const party=(r:any)=>detail.value?.own||r.carrierId===auth.user?.businessEntityId;
const opposite=(r:any)=>r.lastAuthorId!==auth.user?.businessEntityId;
function grainCode(row:any){return options.value.grains.find((g:any)=>g.label===(demandView.value?row.snapshot.grain:row.grains[0]))?.code;}
function selectCard(row:any,checked:any){selected.value=checked?[...selected.value.filter(r=>r.id!==row.id),row]:selected.value.filter(r=>r.id!==row.id);}
function exportRows(){const header=demandView.value?['发布编号','需求名称','起运地','目的地','数量(吨)','状态']:['供给编号','供给名称','起运地','目的地','运力(吨)','运营商'];const body=selected.value.map(r=>demandView.value?[r.businessNo,r.snapshot.name,r.snapshot.originRegion,r.snapshot.destinationRegion,tonnes(r.quantityKg/1000),label(r.status)]:[r.businessNo,r.name,r.origin,r.destination,tonnes(r.capacityKg/1000),r.carrier.name]);const csv=[header,...body].map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='供需匹配.csv';a.click();URL.revokeObjectURL(url);}
onMounted(async()=>{try{options.value=await get('/matches/options');}catch(e){error.value=message(e);}await load();if(route.query.id)await openDetail(String(route.query.id));if(route.query.publishPlan||route.query.publishDemand)await publish(undefined,route.query.publishPlan?String(route.query.publishPlan):undefined,route.query.publishDemand?String(route.query.publishDemand):undefined);});
</script>
<template>
<div class="matches-page">
 <section class="match-panel">
 <div class="hall-header"><el-tabs class="hall-tabs" v-model="tab" @tab-change="switchTab"><el-tab-pane name="demand"><template #label><span class="hall-tab-label"><Icon name="package" :size="19"/>需求大厅</span></template></el-tab-pane><el-tab-pane name="supply"><template #label><span class="hall-tab-label"><Icon name="truck" :size="19"/>供给大厅</span></template></el-tab-pane><el-tab-pane name="mine"><template #label><span class="hall-tab-label"><Icon name="user" :size="19"/>我的</span></template></el-tab-pane></el-tabs></div><div v-if="mine" class="my-match-heading"><div><h3>{{trader?'我发布的需求与方案':carrier?'我发布的运力供给':'我的发布'}}</h3><p>管理本人发布的信息，查看适配的{{trader?'物流运营商':'运输需求'}}。</p></div><el-button v-if="trader&&auth.can('match:publish')" type="primary" @click="publish()"><Icon name="plus" :size="16"/>发布匹配</el-button><el-button v-if="carrier&&auth.can('supply:write')" type="primary" @click="router.push('/supply-demand/supplies')">管理运输供给</el-button></div>
 <form class="match-filters" @submit.prevent="search"><el-input v-model="query.q" clearable placeholder="搜索名称或业务编号" aria-label="搜索名称或业务编号"/><el-select v-if="demandView" v-model="query.status" clearable placeholder="发布状态" aria-label="发布状态"><el-option v-for="s in ['ACTIVE','MATCHED','CLOSED','EXPIRED']" :key="s" :label="label(s)" :value="s"/></el-select><el-select v-if="demandView" v-model="query.type" clearable placeholder="发布对象" aria-label="发布对象"><el-option label="运输需求" value="DEMAND"/><el-option label="完整方案" value="PLAN"/></el-select><el-select v-if="demandView" v-model="query.publicationMode" clearable placeholder="发布方式" aria-label="发布方式筛选"><el-option label="公开发布" value="PUBLIC"/><el-option label="邀约议价" value="DIRECTED"/></el-select><el-select v-model="query.grainId" clearable placeholder="粮食品种" aria-label="粮食品种"><el-option v-for="g in options.grains" :key="g.id" :label="g.label" :value="g.id"/></el-select><el-select v-model="query.modeId" clearable placeholder="运输方式" aria-label="运输方式"><el-option v-for="g in options.modes" :key="g.id" :label="g.label" :value="g.id"/></el-select><el-input v-model="query.origin" placeholder="起运地区" aria-label="起运地区" clearable/><el-input v-model="query.destination" placeholder="目的地区" aria-label="目的地区" clearable/><el-select v-model="query.carrierId" filterable clearable :placeholder="demandView?'指定承运商':'承运主体'" aria-label="承运主体筛选"><el-option v-for="c in options.carriers" :key="c.id" :value="c.id" :label="c.name"/></el-select><el-input-number v-model="query.minQuantity" :controls="false" :min="0" :precision="1" :step="0.1" placeholder="数量下限（吨）" aria-label="数量下限（吨）"/><el-input-number v-model="query.maxQuantity" :controls="false" :min="0" :precision="1" :step="0.1" placeholder="数量上限（吨）" aria-label="数量上限（吨）"/><el-date-picker v-model="query.departureFrom" type="date" value-format="YYYY-MM-DDT00:00:00Z" placeholder="发运 / 服务开始" aria-label="发运时间下限"/><el-date-picker v-model="query.departureTo" type="date" value-format="YYYY-MM-DDT23:59:59Z" placeholder="发运 / 服务结束" aria-label="发运时间上限"/><el-select v-model="query.order" aria-label="排序"><el-option label="最新发布在前" value="desc"/><el-option label="最早发布在前" value="asc"/></el-select><div class="filter-actions"><el-button native-type="submit" type="primary" plain>查询</el-button><el-button @click="reset">重置</el-button></div></form>
 <div class="match-toolbar"><span>{{total}} 条记录 <small v-if="mine">· 匹配推荐仅发布账号可见</small><small v-else-if="demandView">· 公开信息可浏览，报价仅议价双方可见</small><small v-else>· 当前有效的公开运力</small></span><div class="match-view-actions"><el-radio-group v-model="view" aria-label="展示方式" @change="selected=[];syncUrl()"><el-radio-button value="cards">卡片</el-radio-button><el-radio-button value="list">列表</el-radio-button></el-radio-group><el-button :disabled="!selected.length" @click="exportRows">导出已选 {{selected.length||''}}</el-button></div></div>
 <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button @click="load">重试</el-button></el-alert>
 <div v-else-if="view==='cards'" v-loading="loading"><div v-if="rows.length" class="match-card-grid"><article v-for="row in rows" :key="row.id" class="match-business-card" :class="demandView?'match-card--'+businessTone(row.status==='ACTIVE'?row.stage:row.status):''"><header><GrainImage :code="grainCode(row)"/><div><h3>{{demandView?row.snapshot.name:row.name}}</h3><small class="business-number">{{row.businessNo}}</small></div><el-checkbox :model-value="selected.some(r=>r.id===row.id)" :aria-label="'选择 '+(demandView?row.snapshot.name:row.name)" @change="selectCard(row,$event)"/></header><div class="match-card-route"><strong>{{demandView?row.snapshot.originRegion:row.origin}}</strong><span>↓</span><strong>{{demandView?row.snapshot.destinationRegion:row.destination}}</strong></div><div class="match-card-tags"><el-tag type="info" size="small">{{demandView?(row.objectType==='PLAN'?'完整方案':'运输需求'):row.mode}}</el-tag><BusinessStatus v-if="demandView" :status="row.status==='ACTIVE'?row.stage:row.status" :label="label(row.status==='ACTIVE'?row.stage:row.status)" compact/><span>{{demandView?row.snapshot.grain:row.grains.join(' / ')||'粮种不限'}}</span></div><div class="match-card-metrics"><div><small>{{demandView?'待承接数量':'可用运力'}}</small><b>{{demandView?ton(row.remainingKg):supplyRange(row)}}</b></div><div><small>{{demandView?'匹配方式':'参考运价'}}</small><BusinessStatus v-if="demandView&&row.mode==='DIRECTED'" class="match-method-status" status="DIRECTED" label="邀约议价"/><b v-else>{{demandView?'公开竞价':supplyLoading(row)}}</b><small v-for="price in !demandView?supplyQuotes(row):[]" :key="price">{{price}}</small></div></div><p v-if="demandView">截止 {{date(row.deadline)}}</p><small v-if="!demandView">{{row.resourceDescription}}</small><section v-if="mine" class="private-match-overview"><el-alert v-if="row.recommendationError" :title="row.recommendationError" type="error" :closable="false"/><template v-else><div class="private-match-summary"><strong>{{demandView?'匹配物流运营商':'匹配运输需求'}} <b>{{row.recommendationCount}}</b> {{demandView?'家':'条'}}</strong><small>{{demandView?'路线与报价综合排序':'根据本条运力筛选'}}</small></div><ul v-if="row.recommendations.length"><li v-for="r in row.recommendations.slice(0,2)" :key="r.supplyId||r.publicationId"><span>{{demandView?r.carrierName:r.traderName}}<small>{{demandView?r.priceLabel:r.grain+' · '+tonnes(r.quantity)+' 吨'}}{{r.invited?' · 已邀请':''}}</small></span><b>{{r.score}}<small> 分</small></b></li></ul><p v-else>{{emptyRecommendation(row)}}</p></template></section><footer><span>{{demandView?row.trader.name:row.carrier.name}}</span><el-button v-if="mine" type="primary" plain @click="openRecommendations(row)">查看匹配推荐</el-button><el-button v-if="demandView" type="primary" plain @click="openDetail(row.id)">查看详情</el-button><el-button v-else-if="!mine&&trader&&auth.can('match:publish')" type="primary" plain @click="inviteSupply(row)">邀请报价</el-button></footer></article></div><el-empty v-else description="暂无符合条件的记录，请调整筛选或发布匹配" :image-size="65"/></div>
 <el-table v-else :row-class-name="({row}:any)=>demandView?'business-row-'+businessTone(row.status==='ACTIVE'?row.stage:row.status):''" v-loading="loading" :data="rows" row-key="id" @selection-change="selected=$event" empty-text="暂无符合条件的记录，请调整筛选或发布匹配">
 <el-table-column type="selection" width="40"/>
 <el-table-column label="业务信息" min-width="250"><template #default="{row}"><strong>{{demandView?row.snapshot.name:row.name}}</strong><small class="cell-note business-number">{{row.businessNo}}</small><small class="cell-note">{{demandView?row.trader.name:row.carrier.name}}</small></template></el-table-column>
 <el-table-column label="运输线路" min-width="260"><template #default="{row}"><span>{{demandView?row.snapshot.originRegion:row.origin}}</span><small class="cell-note">→ {{demandView?row.snapshot.destinationRegion:row.destination}}</small><small class="cell-note">{{demandView?row.snapshot.modes?.join(' / '):row.mode}}</small></template></el-table-column>
 <el-table-column :label="demandView?'发布与进度':'可用运力'" width="185"><template #default="{row}"><template v-if="demandView"><BusinessStatus :status="row.status==='ACTIVE'?row.stage:row.status" :label="label(row.status==='ACTIVE'?row.stage:row.status)" compact/><small class="cell-note">{{row.objectType==='PLAN'?'完整方案':'运输需求'}} · {{row.mode==='PUBLIC'?'公开':'邀约议价'}}</small><small class="cell-note">{{ton(row.matchedKg)}} / {{ton(row.quantityKg)}} 已确认 · {{label(row.stage)}}</small></template><template v-else><strong>{{supplyRange(row)}}</strong><small class="cell-note">{{row.grains.join(' / ')||'粮种不限'}}</small></template></template></el-table-column>
 <el-table-column :label="demandView?'响应截止':'装载形式 / 报价'" width="185"><template #default="{row}">{{demandView?date(row.deadline):supplyLoading(row)}}<small v-for="price in !demandView?supplyQuotes(row):[]" :key="price" class="cell-note">{{price}}</small><small v-if="demandView" class="cell-note">整单承接</small></template></el-table-column>
 <el-table-column label="操作" fixed="right" :width="mine?165:125"><template #default="{row}"><el-button v-if="demandView" type="primary" link @click="openDetail(row.id)">查看详情</el-button><el-button v-else-if="!mine&&trader&&auth.can('match:publish')" type="primary" link @click="inviteSupply(row)">邀请报价</el-button><span v-else-if="!mine" class="cell-note">{{row.resourceDescription}}</span><el-button v-if="mine" type="primary" link @click="openRecommendations(row)">匹配推荐 {{row.recommendationCount}}</el-button></template></el-table-column>
 </el-table><el-pagination v-model:current-page="query.page" :page-size="query.pageSize" :total="total" layout="total, prev, pager, next" @current-change="syncUrl();load()"/>
 </section>
 <el-drawer v-model="detailOpen" title="匹配详情" size="min(940px, 100vw)" @closed="closed">
 <el-skeleton v-if="detailLoading" :rows="12" animated/><template v-else><el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/><template v-if="detail">
 <div class="match-detail-heading"><div><h2>{{detail.snapshot.name}}</h2><p>{{detail.businessNo}} · {{detail.trader.name}}</p></div><BusinessStatus :status="detail.status" :label="label(detail.status)"/></div>
 <div class="match-summary"><div><small>本次发布数量</small><strong>{{ton(detail.quantityKg)}}</strong></div><div><small>已确认承运</small><strong>{{ton(detail.matchedKg)}}</strong></div><div><small>匹配进度</small><strong>{{label(detail.stage)}}</strong></div></div>
 <div class="match-detail-route">{{detail.snapshot.originRegion}} {{detail.snapshot.originAddress}} <b>→</b> {{detail.snapshot.destinationRegion}} {{detail.snapshot.destinationAddress}}</div>
 <dl class="match-description"><dt>货物</dt><dd>{{[detail.snapshot.grain,detail.snapshot.specification,detail.snapshot.loadingType==='BULK'?'散装':'集装箱'].filter(Boolean).join(' · ')}}</dd><dt>发运 / 到达</dt><dd>{{date(detail.snapshot.departureAt)}} / {{date(detail.snapshot.arrivalAt)}}</dd><dt>运输方式</dt><dd>{{detail.snapshot.modes?.join(' / ')}} · 整单承运</dd><dt>发布方式</dt><dd>{{detail.mode==='PUBLIC'?'公开发布':'邀约议价 · '+(detail.targetCarriers?.map((c:any)=>c.name).join('、')||detail.targetCarrier?.name||'指定物流供应商')}} · {{detail.objectType==='PLAN'?'完整方案':'运输需求'}}</dd><dt>截止 / 单位</dt><dd>{{date(detail.deadline)}} · {{label(detail.quoteType)}}</dd><template v-if="detail.contact"><dt>联系人</dt><dd>{{detail.contact}} {{detail.phone}}</dd></template><dt>说明</dt><dd class="preserve-lines">{{detail.notes||detail.snapshot.notes||'—'}}</dd></dl>
 <el-alert v-if="detail.riskNotes.length" :title="'已确认的适配提醒：'+detail.riskNotes.join('；')" type="warning" :closable="false"/>
 <section v-if="detail.snapshot.plan" class="match-plan"><h3>发布时的完整方案 · {{detail.snapshot.plan.name}}</h3><p v-for="s in detail.snapshot.plan.segments" :key="s.sequence">{{s.sequence}}. {{s.origin.name}} → {{s.destination.name}} <el-tag size="small" type="info">{{label(s.mode)}}</el-tag> {{s.service?.code||s.lineName}}</p><small>参考班列与船期以运营商确认为准，报价覆盖完整运输服务。</small></section>
 <div class="match-actions"><el-button v-if="active&&carrier&&!myResponse&&auth.can('match:quote')" type="primary" @click="editQuote()">提交整单报价</el-button><el-button v-if="active&&detail.own&&auth.can('match:publish')" :disabled="saving" @click="closePublication">关闭发布</el-button><el-button v-if="!active&&detail.own&&detail.status!=='MATCHED'&&auth.can('match:publish')" @click="publish(undefined,undefined,detail.demandId)">重新发布剩余需求</el-button><el-button :disabled="saving" @click="openDetail(detail.id)">刷新详情</el-button></div>
 <section class="match-negotiation"><h3>报价与议价 <small>{{detail.responses.length}} 条{{carrier?' · 仅展示我的报价':''}}</small></h3><el-table v-if="detail.own&&detail.responses.length>1" :data="detail.responses" class="match-compare"><el-table-column label="承运商" min-width="150"><template #default="{row}">{{row.carrier?.name}}</template></el-table-column><el-table-column label="数量（吨）" width="105"><template #default="{row}">{{tonnes(row.terms.quantity)}}</template></el-table-column><el-table-column label="整单总额" width="135"><template #default="{row}">{{money(row.terms.totalCents)}}<small class="cell-note">{{row.terms.taxIncluded?'含税':'不含税'}}</small></template></el-table-column><el-table-column label="承诺到达" width="175"><template #default="{row}">{{date(row.terms.arrivalAt)}}</template></el-table-column><el-table-column label="状态" width="125"><template #default="{row}">{{row.expired&&row.status!=='CONFIRMED'?'报价已过期':label(row.status)}}</template></el-table-column></el-table><el-empty v-if="!detail.responses.length" :description="detail.own?'等待承运商提交报价':carrier?'尚未提交报价':'暂无可查看的议价记录'" :image-size="55"/>
 <article v-for="r in detail.responses" :key="r.id" class="match-response"><header><div><strong>{{r.carrier?.name}}</strong><small class="cell-note">第 {{r.version}} 次更新 · {{date(r.updatedAt)}}</small></div><BusinessStatus :status="r.expired&&!['CONFIRMED','WITHDRAWN','REJECTED'].includes(r.status)?'EXPIRED':r.status" :label="r.expired&&!['CONFIRMED','WITHDRAWN','REJECTED'].includes(r.status)?'报价已过期':label(r.status)"/></header>
 <div class="match-quote-total"><strong>{{money(r.terms.totalCents)}}</strong><span>{{tonnes(r.terms.quantity)}} 吨 · {{money(r.terms.priceCents)}} {{label(r.terms.unit)}} · {{r.terms.taxIncluded?'含税':'不含税'}}</span></div>
 <p>服务：{{date(r.terms.departureAt)}} → {{date(r.terms.arrivalAt)}}</p><p>有效期：{{date(r.terms.validUntil)}} · {{r.terms.followOriginalPlan?'按原需求 / 方案承接':'拟调整方案'}}</p><p class="preserve-lines">承运能力：{{r.terms.capability}}<br/>{{r.terms.note}}</p>
 <div v-if="active&&party(r)&&!platform&&r.status!=='CONFIRMED'" class="match-actions"><el-button v-if="auth.can('match:negotiate')&&(!['WITHDRAWN','REJECTED'].includes(r.status)||carrier)" :disabled="saving" @click="editQuote(r)">{{carrier?'修订报价':'提出议价'}}</el-button><template v-if="r.status==='OPEN'&&opposite(r)&&auth.can('match:negotiate')"><el-button type="primary" plain :disabled="saving||r.expired" @click="act(r,'ACCEPT')">接受条款</el-button><el-button :disabled="saving" @click="act(r,'REJECT')">拒绝条款</el-button></template><el-button v-if="['OPEN','ACCEPTED'].includes(r.status)&&!opposite(r)&&auth.can('match:negotiate')" :disabled="saving" @click="act(r,'WITHDRAW')">撤回条款</el-button><el-button v-if="detail.own&&r.status==='ACCEPTED'&&auth.can('match:confirm')" type="primary" :disabled="saving||r.expired" @click="act(r,'CONFIRM')">确认承运</el-button></div>
 <el-collapse><el-collapse-item title="查看完整议价记录" :name="r.id"><ol class="match-rounds"><li v-for="round in r.rounds" :key="round.id"><strong>{{label(round.action)}}</strong> · {{round.authorName}} · {{date(round.createdAt)}}<p>{{tonnes(round.terms.quantity)}} 吨 · {{money(round.terms.totalCents)}} · {{round.terms.taxIncluded?'含税':'不含税'}} · {{round.terms.capability}}</p><p>服务 {{date(round.terms.departureAt)}} → {{date(round.terms.arrivalAt)}}；有效至 {{date(round.terms.validUntil)}}</p><p v-if="round.note">{{round.note}}</p></li></ol></el-collapse-item></el-collapse>
 <div v-for="c in r.confirmations" :key="c.id" class="match-confirmation"><div><strong>{{label(c.status)}} · {{c.businessNo}}</strong><p>{{ton(c.quantityKg)}} · {{c.status==='INITIALIZATION'?'约定总价':'成交'}} {{money(c.totalCents)}} · {{date(c.confirmedAt)}}</p><p v-if="c.cancelReason">取消原因：{{c.cancelReason}}</p></div><el-button v-if="c.status==='CONFIRMED'&&auth.can('contract:read')" type="primary" @click="router.push({path:'/contracts/signing',query:{confirmationId:c.id}})">合同签署</el-button><el-button v-if="c.status==='CONFIRMED'&&detail.own&&auth.can('match:confirm')" :disabled="saving" @click="cancelConfirmation(c)">取消承运确认</el-button></div>
 </article></section></template></template></el-drawer>
 <el-drawer v-model="recommendationOpen" :title="demandView?'匹配物流运营商':'适合本条运力的运输需求'" size="min(760px, 100vw)"><el-skeleton v-if="recommendationLoading" :rows="8" animated/><el-alert v-else-if="recommendationError" :title="recommendationError" type="error" :closable="false"><el-button :disabled="saving" @click="openRecommendations(recommendationRow)">刷新推荐</el-button></el-alert><template v-else-if="recommendationRow"><div class="recommendation-context"><strong>{{demandView?recommendationRow.snapshot.name:recommendationRow.name}}</strong><p>{{demandView?recommendationRow.snapshot.originRegion:recommendationRow.origin}} → {{demandView?recommendationRow.snapshot.destinationRegion:recommendationRow.destination}}</p><small>匹配结果仅本人可见 · 根据已发布信息筛选，运输条件需双方确认。</small></div><el-empty v-if="!recommendationRow.recommendations.length" :description="emptyRecommendation(recommendationRow)" :image-size="65"/><article v-for="r in recommendationRow.recommendations" :key="r.supplyId||r.publicationId" class="recommended-party"><header><strong>{{demandView?r.carrierName:r.traderName}}</strong><span class="recommendation-score">推荐值 <b>{{r.score}}</b> 分</span></header><p class="recommended-route">{{r.origin}} → {{r.destination}}</p><div class="recommended-facts"><span v-if="!demandView">{{r.grain}} · {{tonnes(r.quantity)}} 吨</span><span v-if="!demandView">{{r.businessNo}}</span><span>路线匹配 {{r.routeMatch}}%</span><span>{{demandView?'已接单':'已落实运输'}} {{r.acceptedOrders}} 笔</span><span>注册地 {{r.registeredRegion}}</span></div><div class="recommended-price"><strong>{{r.unitPriceCents==null?'价格待协商':money(r.unitPriceCents)+'/吨'}}</strong><small>{{demandView?r.priceLabel:'本条运力参考价'}} · 整程参考 {{r.totalCents==null?'待协商':money(r.totalCents)}}</small></div><p v-if="!demandView" class="recommended-facts">发运 {{date(r.departureAt)}} · 要求到达 {{date(r.arrivalAt)}}</p><div class="recommended-reasons"><el-tag v-for="reason in r.reasons" :key="reason" size="small" type="info" effect="plain">{{reason}}</el-tag></div><small v-for="warning in r.warnings" :key="warning" class="recommended-warning">{{warning}}</small><footer><BusinessStatus v-if="r.invited" status="DIRECTED" label="已邀请报价" compact/><span v-else>可发起报价协商</span><el-button v-if="demandView" type="primary" :disabled="saving||r.invited||r.hasResponse" :loading="saving" @click="inviteRecommended(r)">{{r.hasResponse?'已收到报价':r.invited?'已邀请':'邀请报价'}}</el-button><el-button v-else type="primary" :disabled="saving" @click="quoteRecommended(r)">{{r.response?'查看我的报价':'前往报价'}}</el-button></footer></article></template></el-drawer>
 <el-dialog v-model="inviteOpen" title="邀请物流运营商报价" width="min(560px, 94vw)" :close-on-press-escape="!saving" :close-on-click-modal="!saving" :show-close="!saving"><el-alert v-if="inviteError" :title="inviteError" type="error" :closable="false"/><p>邀请 {{inviteSupplyRow?.carrier.name}}，从本人已发布的需求或方案中选择本次运输任务。</p><el-skeleton v-if="inviteLoading" :rows="3" animated/><el-form v-else-if="invitePublications.length" label-position="top" :disabled="saving"><el-form-item label="我的有效发布" required><el-select v-model="invitePublicationId" filterable aria-label="我的有效发布"><el-option v-for="p in invitePublications" :key="p.id" :value="p.id" :label="p.name+' · '+tonnes(p.quantity)+' 吨 · '+p.businessNo"/></el-select></el-form-item></el-form><el-empty v-else description="本人暂无有效发布，请先在“我的”发布运输需求" :image-size="60"/><template #footer><el-button :disabled="saving" @click="inviteOpen=false">取消</el-button><el-button v-if="!invitePublications.length&&!inviteLoading" type="primary" @click="inviteOpen=false;publish(inviteSupplyRow)">发布需求并邀请</el-button><el-button v-else type="primary" :disabled="!invitePublicationId||inviteLoading" :loading="saving" @click="sendSupplyInvitation">发送邀请</el-button></template></el-dialog>
 <el-dialog v-model="publishOpen" title="发布匹配" width="min(660px, 94vw)" :close-on-click-modal="false" :show-close="!saving" :close-on-press-escape="!saving">
 <el-alert v-if="publishError" :title="publishError" type="error" :closable="false"/><el-alert v-if="supply" :title="'邀请对象：'+supply.carrier.name" type="info" :closable="false"/>
 <el-form label-position="top" :disabled="saving">
 <el-form-item label="选择我的运输需求" required><el-select v-model="publication.demandId" filterable aria-label="选择我的运输需求" @change="publication.planRunId='' "><el-option v-for="d in options.demands" :key="d.id" :value="d.id" :label="d.name+' · 剩余 '+ton(d.quantityKg-d.matchedKg)"/></el-select><small>仅展示本人创建、有剩余数量且没有有效发布的需求。</small></el-form-item>
 <el-form-item label="发布对象"><el-select v-model="publication.planRunId" clearable placeholder="直接发布运输需求" aria-label="选择完整方案" @change="publication.allowPartial=false"><el-option v-for="p in demand?.plans||[]" :key="p.id" :value="p.id" :label="p.businessNo+' · v'+p.version"/></el-select></el-form-item>
 <el-form-item label="发布方式"><el-radio-group v-model="publication.mode" :disabled="!!supply"><el-radio value="PUBLIC">公开发布</el-radio><el-radio value="DIRECTED">邀约议价</el-radio></el-radio-group></el-form-item>
 <el-form-item v-if="publication.mode==='DIRECTED'" label="邀约物流运营商（可多选）" required><el-select v-model="publication.targetCarrierIds" multiple filterable :multiple-limit="10" aria-label="邀约物流运营商（可多选）"><el-option v-for="c in options.carriers" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item>
 <el-form-item label="响应截止时间" required><el-date-picker v-model="publication.deadline" type="datetime" aria-label="响应截止时间" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="不晚于发运时间"/><small v-if="demand">计划发运：{{date(demand.departureAt)}}</small></el-form-item>
 <el-form-item label="报价单位"><el-radio-group v-model="publication.quoteType"><el-radio value="TOTAL">总价（元/单）</el-radio><el-radio value="PER_TON">单价（元/吨）</el-radio></el-radio-group></el-form-item>
 
